SELECT c.city, CASE WHEN c.age >= 60 THEN 'high' WHEN c.age >= 25 THEN 'mid' ELSE 'low' END AS age_bucket, SUM(CASE WHEN o.status = 'CANCELLED' THEN o.discount ELSE 0 END) AS cancelled_discount, MIN(o.shipping_fee) AS min_shipping_fee FROM orders o JOIN stores s ON o.store_id = s.id LEFT OUTER JOIN customers c ON o.customer_id = c.id WHERE o.customer_id = 36 GROUP BY c.city, CASE WHEN c.age >= 60 THEN 'high' WHEN c.age >= 25 THEN 'mid' ELSE 'low' END
